  ag_workflow_sub: { en: 'What this agent will execute — every step is reviewable after the run.', hi: 'यह एजेंट क्या निष्पादित करेगा — हर चरण बाद में समीक्षा योग्य है।', mr: 'हा एजंट काया करेल — प्रत्येक पायरी नंतर तपासता येऊ शकते.', ta: 'இந்த ஏஜென்ட் என்ன செய்யும் — ஒவ்வொரு படிநிலையும் பின்னர் மதிப்பிடலாம்.', te: 'ఈ ఏజెంట్ ఏమి చేస్తుంది — ప్రతి దశను తర్వాత సమీక్షించవచ్చు.', kn: 'ಈ ಏಜೆಂಟ್ ಏನು ಮಾಡುತ್ತದೆ — ಪ್ರತಿ ಹಂತವನ್ನು ನಂತರ ಪರಿಶೀಲಿಸಬಹುದು.', bn: 'এই এজেন্ট যা কী করবে — প্রতিটি ধাপ পরে পর্যালোচনা করা যায়।', gu: 'આ એજન્ટ શું કરશે — દરેક પગલો પછી તપાસી શકાય છે.', ml: 'ഈ ഏജന്റ് എന്ത് ചെയ്യും — ഓരോ ഘട്ടവും പിന്നീട് അവലോകനം ചെയ്യാം.', sa: 'सः एजेण्टः किम् करिष्यति — प्रत्येकं पदम् अनन्तरं परीक्षणीयम्।' },
  ag_dismiss: { en: 'Dismiss', hi: 'बंद करें', mr: 'बंद करा', ta: 'மூடு', te: 'మూసివేయి', kn: 'ಮುಚ್ಚಿ', bn: 'বাতিল', gu: 'બંધ કરો', ml: 'അടയ്ക്കുക', sa: 'पिधानयतु' },
  ag_prefilled_brief: { en: 'Prefilled from your Orchestrator brief', hi: 'आपके ऑर्केस्ट्रेटर ब्रीफ से पहले से भरा गया', mr: 'तुमच्या ऑर्केस्ट्रेटर ब्रीफमधून आधीच भरलेले', ta: 'உங்கள் ஆர்க்கெஸ்ட்ரேட்டர் சுருக்கமிலிருந்து முன்பே நிரப்பப்பட்டது', te: 'మీ ఆర్కెస్ట్రేటర్ బ్రీఫ్ నుండి ముందుగానే నింపబడింది', kn: 'ನಿಮ್ಮ ಆರ್ಕೆಸ್ಟ್ರೇಟರ್ ಬ್ರೀಫ್‌ನಿಂದ ಮೊದಲೇ ತುಂಬಿಸಲಾಗಿದೆ', bn: 'আপনার অর্কেস্ট্রেটর ব্রিফ থেকে আগেই পূরণ করা', gu: 'તમારા ઑર્કેસ્ટ્રેટર બ્રીફમાંથી પહેલેથી ભરેલું', ml: 'നിങ്ങളുടെ ഓർക്കസ്ട്രേറ്റർ ബ്രീഫിൽ നിന്ന് മുൻകൂട്ടി പൂരിപ്പിച്ചിരിക്കുന്നു', sa: 'भवतः आर्केस्ट्रेटर-ब्रीफात् पूर्वम् पूरितम्' },
  ag_clear_reenter: { en: 'Clear & re-enter', hi: 'साफ़ करें और पुनः भरें', mr: 'रद्द करा आणि पुन्हा भरा', ta: 'அழித்து மீண்டும் உள்ளிடவும்', te: 'తెలిపి మళ్లీ నమోదు చేయండి', kn: 'ಅಳಿಸಿ ಮತ್ತೆ ನಮೂದಿಸಿ', bn: 'পরিষ্কার করে আবার লিখুন', gu: 'સાફ કરો અને ફરી भरो', ml: 'മായ്ക്കുക, വീണ്ടും നമൂദിക്കുക', sa: 'शोधयतु पुनः लिखतु' },
  ag_upload_doc: { en: 'Upload a document for the agent to read', hi: 'एजेंट के पढ़ने के लिए दस्तावेज़ अपलोड करें', mr: 'एजंटला वाचण्यासाठी दस्तऐवज अपलोड करा', ta: 'ஏஜென்ட் படிக்க ஆவணத்தைப் பதிவேற்றவும்', te: 'ఏజెంట్ చదవడానికి పత్రాన్ని అప్‌లోడ్ చేయండి', kn: 'ಏಜೆಂಟ್ ಓದಲು ದಾಖಲೆ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ', bn: 'এজেন্ট পড়ার জন্য নথি আপলোড করুন', gu: 'એજન્ટ વાંચે તે માટે દસ્તાવેજ અપલોડ કરો', ml: 'ഏജന്റ് വായിക്കാൻ രേഖ അപ്‌ലോഡ് ചെയ്യുക', sa: 'पठितुं एजेण्टाय पत्रं अपलोडयतु' },
  ag_upload_doc_sub: { en: 'PDF · DOCX · TXT · MD · CSV · image (OCR) — Send it straight to the agent, or answer the guided questions below (your choice).', hi: 'PDF · DOCX · TXT · MD · CSV · छवि (OCR) — इसे सीधे एजेंट को भेजें, या नीचे दिए प्रश्नों के उत्तर दें (आपकी सुविधा)।', mr: 'PDF · DOCX · TXT · MD · CSV · प्रतिमा (OCR) — हे थेट एजंटला पाठवा, किंवा खालील प्रश्नांची उत्तरे द्या (तुमची सोय)।', ta: 'PDF · DOCX · TXT · MD · CSV · படம் (OCR) — அதை நேரடியாக ஏஜென்டிடம் அனுப்புங்கள் அல்லது கீழே உள்ள கேள்விகளுக்கு பதிலளியுங்கள் (உங்கள் விருப்பம்).', te: 'PDF · DOCX · TXT · MD · CSV · చిత్రం (OCR) — దీన్ని నేరుగా ఏజెంట్‌కు పంపండి, లేదా కింది ప్రశ్నలకు సమాధానాలు ఇవ్వండి (మీ ఎంపిక).', kn: 'PDF · DOCX · TXT · MD · CSV · ಚಿತ್ರ (OCR) — ಅದನ್ನು ನೇರವಾಗಿ ಏಜೆಂಟ್‌ಗೆ ಕಳುಹಿಸಿ, ಅಥವಾ ಕೆಳಗಿನ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಿಸಿ (ನಿಮ್ಮ ಆಯ್ಕೆ).', bn: 'PDF · DOCX · TXT · MD · CSV · ছবি (OCR) — সরাসরি এজেন্টকে পাঠান, বা নিচের প্রশ্নের উত্তর দিন (আপনার পছন্দ)।', gu: 'PDF · DOCX · TXT · MD · CSV · છબી (OCR) — તેને સીધું એજન્ટને મોકલો, અથવા નીચેના પ્રશ્નોના જવાબ આપો (તમારી પસંદ).', ml: 'PDF · DOCX · TXT · MD · CSV · ചിത്രം (OCR) — അത് നേരിട്ട് ഏജന്റിന് അയയ്ക്കുക, അല്ലെങ്കിൽ താഴെയുള്ള ചോദ്യങ്ങൾക്ക് മറുപടി നൽകുക (നിങ്ങളുടെ തിരഞ്ഞെടുപ്പ്).', sa: 'PDF · DOCX · TXT · MD · CSV · चित्रम् (OCR) — तत् सीधम् एजेण्टाय प्रेषयतु अथवा अधःप्रश्नानाम् उत्तराणि ददातु (भवतः विकल्पः)।' },
  ag_reading: { en: 'Reading…', hi: 'पढ़ा जा रहा है…', mr: 'वाचत आहे…', ta: 'படிக்கப்படுகிறது…', te: 'చదవబడుతోంది…', kn: 'ಓದಲಾಗುತ್ತಿದೆ…', bn: 'পড়া হচ্ছে…', gu: 'વાંચી રહ્યું છે…', ml: 'വായിക്കുന്നു…', sa: 'पठ्यते…' },
