  ag_chars_read: { en: '{n} chars read', hi: '{n} अक्षर पढ़े गए', mr: '{n} अक्षर वाचले', ta: '{n} எழுத்துகள் படிக்கப்பட்டன', te: '{n} అక్షరాలు చదవబడ్డాయి', kn: '{n} ಅಕ್ಷರಗಳು ಓದಲಾದವು', bn: '{n} অক্ষর পঠিত', gu: '{n} અક્ષરો વંચાયા', ml: '{n} അക്ഷരങ്ങൾ വായിച്ചു', sa: '{n} अक्षराणि पठितानि' },
  ag_running: { en: 'Running…', hi: 'चल रहा है…', mr: 'चालू आहे…', ta: 'இயக்கப்படுகிறது…', te: 'నడుస్తోంది…', kn: 'ಓಡುತ್ತಿದೆ…', bn: 'চলছে…', gu: 'ચાલી રહ્યું છે…', ml: 'ഓടുന്നു…', sa: 'चलति अस्ति…' },
  ag_send_to_agent: { en: 'Send to agent', hi: 'एजेंट को भेजें', mr: 'एजंटला पाठवा', ta: 'ஏஜென்டிடம் அனுப்பு', te: 'ఏజెంట్‌కు పంపండి', kn: 'ಏಜೆಂಟ్‌ಗೆ ಕಳುಹಿಸಿ', bn: 'এজেন্টকে পাঠান', gu: 'એજન્ટને મોકલો', ml: 'ഏജന്റിന് അയയ്ക്കുക', sa: 'एजेण्टाय प्रेषयतु' },
