  ag_question_of: { en: 'Question {n} of {m}', hi: 'प्रश्न {n} / {m}', mr: 'प्रश्न {n} / {m}', ta: 'கேள்வி {n} / {m}', te: 'ప్రశ్న {n} / {m}', kn: 'ಪ್ರಶ್ನೆ {n} / {m}', bn: 'প্রশ্ন {n} / {m}', gu: 'પ્રશ્ન {n} / {m}', ml: 'ചോദ്യം {n} / {m}', sa: 'प्रश्नः {n} / {m}' },
  ag_confirm_understanding: { en: 'Confirm the agent\'s understanding', hi: 'एजेंट की समझ की पुष्टि करें', mr: 'एजंटच्या समजुतेची खात्री करा', ta: 'ஏஜென்டின் புரிதலை உறுதிசெய்யுங்கள்', te: 'ఏజెంట్ అర్థాన్ని నిర్ధారించండి', kn: 'ಏಜೆಂಟ್‌ನ ಅರಿವನ್ನು ದೃಢಪಡಿಸಿ', bn: 'এজেন্টের বোঝা নিশ্চিত করুন', gu: 'એજન્ટની સમજણ પુષ્ટિ કરો', ml: 'ഏജന്റിന്റെ മനസ്സിലാക്കൽ ഉറപ്പുകളാക്കുക', sa: 'एजेण्टस्य अवगमनं पुष्ट्यतु' },
  ag_review_run: { en: 'Review & run', hi: 'समीक्षा करें और चलाएँ', mr: 'तपासा आणि चालवा', ta: 'மதிப்பிட்டு இயக்கவும்', te: 'సమీక్షించి నడపండి', kn: 'ಪರಿಶೀಲಿಸಿ ಓಡಿ', bn: 'পর্যালোচনা করে চালান', gu: 'તપાસો અને ચલાવો', ml: 'അവലോകനം ചെയ്ത് ഓടിക്കുക', sa: 'परीक्ष्य अनन्तरं प्रचलयतु' },
  ag_required: { en: 'required', hi: 'आवश्यक', mr: 'आवश्यक', ta: 'கட்டாயம்', te: 'అవసరం', kn: 'ಅಗತ್ಯ', bn: 'আবশ্যক', gu: 'આવશ્યક', ml: 'ആവശ്യമാണ്', sa: 'आवश्यकम्' },
