  ag_disclaimer: { en: 'AI-assisted research material — must be reviewed by a qualified professional. Not legal, medical, safety, regulatory, or patentability advice.', hi: 'AI-सहायता अनुसंधान सामग्री — योग्य पेशेवर द्वारा समीक्षा आवश्यक। यह कानूनी, चिकित्सकीय, सुरक्षा, नियामक या पेटेंटेबिलिटा सलाह नहीं है।', mr: 'AI-सहाय्य संशोधन सामग्री — सक्ष्म व्यावसायिकाने तपासणी आवश्यक. ही कायदा, वैद्यकीय, सुरक्षा, नियामक किंवा पेटंटेबिलिटी सल्ला नाही.', ta: 'AI உதவியுடைய ஆராய்ச்சி பொருள் — தகுதமுள்ள நிபுணரால் மதிப்பிடப்பட வேண்டும். இது சட்ட, மருத்துவ, பாதுகாப்பு, ஒழுங்குமுறை அல்லது காப்புரிமை ஆலோசனை அல்ல.', te: 'AI సహాయంతో సేకరించిన పరిశోధన విషయం — నైపుణ్యంగల వృత్తిసేతుడు సమీక్షించాలి. ఇది చట్టపరమైన, వైద్య, భద్రతా, నియంత్రణ లేదా పేటెంట్ చాత్ర్యం కాదు.', kn: 'AI ನಿರ್ದರ್ಶನದ ಸಂಶೋಧನಾ ಸಾಮಗ್ರಿ — ಅರ್ಹ ತಜ್ಞರಿಯಿಂದ ಪರಿಶೀಲನೆ ಅಗತ್ಯ. ಇದು ಕಾನೂನು, ವೈದ್ಯ, ಸುರಕ್ಷತೆ, ನಿಯಂತ್ರಣ ಅಥವಾ ಪೇಟೆಂಟ್ ಸಲಹೆ ಅಲ್ಲ.', bn: 'AI-সহায়ত গবেষণা উপকরণ — যোগ্য পেশাদার দ্বারা পর্যালোচনা আবশ্যক। এটি আইনি, চিকিৎসা, নিরাপত্তা, নিয়ন্ত্রক বা প্যাটেন্টেবিলিটি পরামর্শ নয়।', gu: 'AI-સહાય સંશોધન સામગ્રી — લાયક વ્યાવસાયિકે તપાસવી પડશે. આ કાયદાની, તબીબતી, સુરક્ષા, નિયામક કે પેટેન્ટેબિલિટી સલાહ નથી.', ml: 'AI-സഹായ ഗവേഷണ സാമഗ്രി — യോഗതാമുക്തനായ വിദഗ്ധനാലുള്ള അവലോകനം അത്യവസായം. ഇത് നിയമ, വൈദ്യ, സുരക്ഷ, നിയന്ത്രണ അല്ലെങ്കിൽ പേറ്റന്റബിലിറ്റി ഉപദേശമല്ല.', sa: 'कृत्रिमप्रज्ञा-सहायित-अनुसन्धानसामग्री — योग्य-विद्वानेन परीक्षणम् आवश्यकम्। इयं विधि-, चिकित्सा-, सुरक्षा-, नियामक- अथवा पटेण्ट-योग्यता-मन्त्रणं न।' },
  ag_proceed_review: { en: 'Proceed to review', hi: 'समीक्षा हेतु आगे बढ़ें', mr: 'तपासणीसाठी पुढे जा', ta: 'மதிப்பிடச் செல்லவும்', te: 'సమీక్షకు వెళ్లండి', kn: 'ಪರಿಶೀಲನೆಗೆ ಸಾಗಿ', bn: 'পর্যালোচনায় যান', gu: 'તપાસ માટે આગળ વધો', ml: 'അവലോകനത്തിലേക്ക് പോകുക', sa: 'समीक्षणं प्रति अग्रसरतु' },
  escalate_subject: { en: 'IP-SAKTI — IP facilitator request', hi: 'IP-SAKTI — IP सुविधाकर्ता अनुरोध', mr: 'IP-SAKTI — IP सुविधापदार्थव्यक्ती विनंती', ta: 'IP-SAKTI — IP இசைவு கோரிக்கை', te: 'IP-SAKTI — IP సౌహార్థ అభ్యర్థన', kn: 'IP-SAKTI — IP ಸೌಹಾರ್ಥ ಮನವಿ', bn: 'IP-SAKTI — IP ফ্যাসিলিটেটর অনুরোধ', gu: 'IP-SAKTI — IP ફેસિલિટેટર વિનંતી', ml: 'IP-SAKTI — IP ഫാസിലിറ്റേറ്റർ അപേക്ഷ', sa: 'IP-SAKTI — IP-सुविधापदार्थव्यक्तेः प्रार्थना' },
